//! The live-state preamble: what the model knows about the user's shell this turn.
//!
//! It is regenerated by the daemon on every turn from the prompt's `ShellContext`, the
//! last command that `prompt.send` carried in memory, the scope derivation and the
//! machine facts, and it rides as the first block of the turn's prompt. The prompt is
//! saved with the preamble, and every later request sends it again word for word, so
//! each request starts with the request before it (the README, "The history only
//! grows"). An old preamble is a record of its moment: the first line of every block
//! tells the model that only the newest one is current ([`CURRENT_RULE`]), also under a
//! system prompt that the user replaced. The last command is shown with its
//! secrets redacted ([`secrets::redact`]), because the store keeps what the model read.
//! The static rules live apart from it, in the system prompt, except the rules about
//! the turn's settings: they ride here next to the mode, the model and the effort they
//! are about, and a system prompt that the user replaced in `config.toml` cannot lose
//! them.
//!
//! The list of the modes names `full` only when the user allowed full mode
//! (`permissions.allow_full`) or the turn runs in it. With full mode off the preamble is
//! byte for byte what it was before full mode existed, so no prompt cache breaks.

mod secrets;

use std::fmt::{self, Write as _};
use std::path::PathBuf;

use efr_permissions::Egress;
use efr_protocol::{Mode, ModeFallback};
use efr_scope::Repo;

/// The longest last command shown, in characters; a longer one is cut with a marker.
const COMMAND_MAX_CHARS: usize = 400;

/// The state of the user's shell and machine for one turn.
///
/// `Debug` leaves out the last command, which can hold a secret such as
/// `export TOKEN=...`.
#[derive(Clone, PartialEq, Eq)]
pub(crate) struct LiveState {
    /// The user's working directory.
    pub(crate) cwd: PathBuf,
    /// The user's previous directory, `$OLDPWD`.
    pub(crate) oldpwd: Option<PathBuf>,
    /// The last command line from the user's history.
    pub(crate) last_command: Option<String>,
    /// The exit status of the last command, `$?`.
    pub(crate) last_status: Option<i32>,
    /// The git work tree around the working directory.
    pub(crate) repo: Option<Repo>,
    /// The user's home directory.
    pub(crate) home: PathBuf,
    /// The host name.
    pub(crate) host: Option<String>,
    /// The operating system and distribution, such as `Arch Linux`.
    pub(crate) os: Option<String>,
    /// True when the user's shell runs over SSH.
    pub(crate) ssh: bool,
    /// The conversation's `$SCRATCH`.
    pub(crate) scratch: PathBuf,
    /// Where the conversation's hidden shell last reported to be, when it differs from
    /// the user's directory.
    pub(crate) agent_cwd: Option<PathBuf>,
    /// The user's directory at the previous prompt, when the user moved since then.
    pub(crate) moved_from: Option<PathBuf>,
    /// The turn's permission mode.
    pub(crate) mode: Mode,
    /// Why the turn runs with a stricter mode than it asked for, such as `auto` without
    /// a working sandbox.
    pub(crate) fallback: Option<ModeFallback>,
    /// The turn's model.
    pub(crate) model: String,
    /// The turn's reasoning effort; `None` leaves it to the backend.
    pub(crate) effort: Option<String>,
    /// How contained commands reach the network: the egress of the engine that decides
    /// the turn's calls, which the rule of `auto` names (phase D2).
    pub(crate) egress: Egress,
    /// True when the user allowed full mode (`permissions.allow_full`): the list of the
    /// modes names it. A full turn names it anyway.
    pub(crate) full_allowed: bool,
}

impl fmt::Debug for LiveState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // NOTE: last_command is deliberately missing; see the type's doc comment.
        f.debug_struct("LiveState")
            .field("cwd", &self.cwd)
            .field("oldpwd", &self.oldpwd)
            .field("last_status", &self.last_status)
            .field("repo", &self.repo)
            .field("home", &self.home)
            .field("host", &self.host)
            .field("os", &self.os)
            .field("ssh", &self.ssh)
            .field("scratch", &self.scratch)
            .field("agent_cwd", &self.agent_cwd)
            .field("moved_from", &self.moved_from)
            .field("mode", &self.mode)
            .field("fallback", &self.fallback)
            .field("model", &self.model)
            .field("effort", &self.effort)
            .field("full_allowed", &self.full_allowed)
            .finish_non_exhaustive()
    }
}

impl LiveState {
    /// The preamble text: one fact per line inside a `<live_state>` block, so the model
    /// can tell it from the user's words.
    pub(crate) fn render(&self) -> String {
        let mut text = String::from("<live_state>\n");
        text.push_str(CURRENT_RULE);
        // NOTE: writing to a String cannot fail, so the results are ignored.
        let _ = write!(text, "The user's shell is in {}", self.cwd.display());
        match &self.oldpwd {
            Some(oldpwd) => {
                let _ = writeln!(text, "; the previous directory was {}.", oldpwd.display());
            }
            None => text.push_str(".\n"),
        }
        text.push_str(
            "Commands you run with the shell tool start there in a new hidden shell; \
             the hidden shell keeps its own directory between calls.\n",
        );
        let agent_cwd = self.agent_cwd.as_ref().filter(|dir| **dir != self.cwd);
        // NOTE: without this line the model reads a short follow-up, such as `and the
        // tests?`, as about the directory of the previous prompt.
        match (self.moved_from.as_ref().filter(|dir| **dir != self.cwd), agent_cwd) {
            (Some(from), None) => {
                let _ = writeln!(
                    text,
                    "The user moved from {} to {} since the last prompt; your hidden shell \
                     moved with them.",
                    from.display(),
                    self.cwd.display()
                );
            }
            (Some(from), Some(agent_cwd)) => {
                let _ = writeln!(
                    text,
                    "The user moved from {} to {} since the last prompt; your hidden shell \
                     could not move with them and is still in {}.",
                    from.display(),
                    self.cwd.display(),
                    agent_cwd.display()
                );
            }
            (None, Some(agent_cwd)) => {
                let _ = writeln!(text, "Your hidden shell is in {}.", agent_cwd.display());
            }
            (None, None) => {}
        }
        if let Some(command) = &self.last_command {
            text.push_str(&last_command(command, self.last_status));
        } else if let Some(status) = self.last_status {
            let _ = writeln!(text, "The user's last command exited with status {status}.");
        }
        if let Some(repo) = &self.repo {
            let _ = write!(text, "Git work tree: {}", repo.root.display());
            match &repo.branch {
                Some(branch) => {
                    let _ = writeln!(text, ", branch {branch}.");
                }
                None => text.push_str(", detached HEAD.\n"),
            }
        }
        let _ = writeln!(text, "Home: {}", self.home.display());
        match (&self.host, &self.os) {
            (Some(host), Some(os)) => {
                let _ = writeln!(text, "Host: {host} ({os})");
            }
            (Some(host), None) => {
                let _ = writeln!(text, "Host: {host}");
            }
            (None, Some(os)) => {
                let _ = writeln!(text, "OS: {os}");
            }
            (None, None) => {}
        }
        if self.ssh {
            text.push_str("The user's shell runs over SSH.\n");
        }
        let _ = writeln!(
            text,
            "$SCRATCH: {} (your own directory for files; writing there needs no approval \
             except in manual mode)",
            self.scratch.display()
        );
        text.push_str(&mode_line(self.mode));
        if let Some(fallback) = &self.fallback {
            // NOTE: the model must know that the mode it reads is not the one the user
            // chose, or it would promise what the asked mode allows.
            let _ = writeln!(
                text,
                "The user asked for {}, but this turn runs as {}: {}.",
                fallback.asked,
                self.mode,
                fallback.reason.trim_end_matches('.')
            );
        }
        let _ = writeln!(text, "Model: {}", self.model);
        match &self.effort {
            Some(effort) => {
                let _ = writeln!(text, "Reasoning effort: {effort}");
            }
            None => text.push_str("Reasoning effort: the backend's default for the model\n"),
        }
        // NOTE: with full mode off the list stays as it was, word for word (DF18).
        let modes: &[Mode] = if self.full_allowed || self.mode == Mode::Full {
            text.push_str("efr has four permission modes and no others:\n");
            &[Mode::Manual, Mode::Cautious, Mode::Auto, Mode::Full]
        } else {
            text.push_str("efr has three permission modes and no others:\n");
            &[Mode::Manual, Mode::Cautious, Mode::Auto]
        };
        for mode in modes {
            let _ = writeln!(text, "- {mode}: {}", mode_rule(*mode, self.egress));
        }
        text.push_str(SETTINGS_RULES);
        text.push_str("</live_state>");
        text
    }
}

/// The first line of every block: which block is current. Each request sends the
/// preambles of the earlier prompts again, word for word, so the model must not read an
/// old directory or mode as the current one. The line rides in the block, so a system
/// prompt that the user replaced in `config.toml` cannot lose it.
const CURRENT_RULE: &str = "\
This block shows the state when the user sent this prompt. Only the newest live_state \
block is current; an older one shows the state at its own prompt.
";

/// Who changes the turn's settings, after the list of the real permission modes. A
/// model that is not told invents modes and claims to switch them when a prompt only
/// names one, such as `mode cautious` sent from sticky mode, although it has no way to
/// switch anything.
const SETTINGS_RULES: &str = "\
Only the user changes this terminal's mode, model and effort, with the lines ,mode \
,model and ,effort in their shell, such as ,mode auto; in sticky mode a bare line such \
as mode auto works too. You cannot change them, and nothing you do changes them for \
this turn, so never say that you switched or will switch one: tell the user which line \
to type. Your settings tool changes only the defaults in config.toml, after the user \
approves its diff, from the next turn on, and a terminal's own choice still wins over \
them.
";

/// The line that names the turn's permission mode; the list of the modes below it
/// says what each one means, so the rule of a mode is written once.
fn mode_line(mode: Mode) -> String {
    match mode {
        Mode::Manual | Mode::Cautious | Mode::Auto | Mode::Full => {
            format!("Permission mode: {mode}\n")
        }
        // NOTE: a mode added to the protocol after this crate was written.
        _ => "Permission mode: one this build does not know; calls it does not allow ask \
              the user.\n"
            .to_owned(),
    }
}

/// The rule of `auto` up to its sentence about access failures (efr's auto spec, 13.7),
/// without its leading "In auto, ", because the list prints `- auto: <rule>`.
const AUTO_RULE_HEAD: &str = "do what the user asks. The request is the permission. Never \
                              tell the user that you lack permission before you try. Run the \
                              command, and efr decides: it runs it in a sandbox, or it asks \
                              its reviewer or the user. efr reads sudo, a push or systemctl \
                              in the line itself, so run such commands as they are. Shell \
                              commands read files as the user does, and secrets read as \
                              empty. They write in the turn's project (when there is one), \
                              $SCRATCH, /tmp and tool caches; /tmp and the caches are private \
                              to this conversation, so share files with the user through \
                              $SCRATCH. When a command fails for access, call shell again \
                              with the narrowest needs and a short reason.";

/// The sentence of the rule of `auto` when contained commands reach the network
/// through efr's proxy (phase D2, DP28).
const AUTO_RULE_PROXY: &str = " Shell commands reach package registries and GitHub through \
                               efr's proxy; for another host, efr asks its reviewer.";

/// The rest of the rule of `auto`.
const AUTO_RULE_TAIL: &str = " A command that runs outside the sandbox, such as sudo or a \
                              push, must be alone in its call. For long work, such as a \
                              server or a monitor, call shell with background: true; you get \
                              a notice when it ends, so do not poll. If efr refuses an \
                              action, do not try it another way. In the sandbox, tty and $$ \
                              can differ from the host.";

/// The rule of full mode (efr's full mode, DF18): what runs, and what efr still denies or
/// asks about. It promises no more than efr reads in a line.
const FULL_RULE: &str = "do what the user asks. Commands run as the user, with no sandbox \
                         and no question. efr still denies secrets, its own config and its \
                         own dirs, and asks the user before sudo, before a process that \
                         outlives the turn and before a delete of ~, /, a system dir or a \
                         project. If efr refuses an action, do not try it another way. For \
                         long work, call shell with background: true.";

/// What runs without a question in `mode`, as `docs/permissions.md` states it. The rule
/// of `auto` says how contained commands reach the network: nothing with no proxy
/// (`egress`), the proxy's sentence with it.
fn mode_rule(mode: Mode, egress: Egress) -> String {
    let rule = match mode {
        Mode::Manual => {
            "every read, write, command and network access asks the user, except what the \
             user's own rules allow."
        }
        Mode::Cautious => {
            "reads outside secrets, the read-only commands, and writes in $SCRATCH and in \
             the turn's registered project run at once; other calls ask the user."
        }
        Mode::Auto => {
            let proxy = if egress == Egress::Proxy { AUTO_RULE_PROXY } else { "" };
            return format!("{AUTO_RULE_HEAD}{proxy}{AUTO_RULE_TAIL}");
        }
        Mode::Full => FULL_RULE,
        _ => "calls it does not allow ask the user.",
    };
    rule.to_owned()
}

/// The line or block that shows the last command and its status. The secrets go
/// before the cut, so a cut never leaves a part of one.
fn last_command(command: &str, status: Option<i32>) -> String {
    let command = cut(&secrets::redact(command.trim_end()));
    if command.contains('\n') || command.contains('`') {
        let status = match status {
            Some(status) => format!(", which exited with status {status}"),
            None => String::new(),
        };
        format!("The user's last command{status}:\n```\n{command}\n```\n")
    } else {
        let status = match status {
            Some(status) => format!("; it exited with status {status}"),
            None => String::new(),
        };
        format!("The user's last command was `{command}`{status}.\n")
    }
}

/// `text` cut to [`COMMAND_MAX_CHARS`] characters, with a marker when cut.
fn cut(text: &str) -> String {
    match text.char_indices().nth(COMMAND_MAX_CHARS) {
        Some((at, _)) => format!("{} [cut]", &text[..at]),
        None => text.to_owned(),
    }
}

